function m=v3_analyze(r,s,folder)
p=vehicle_params;bank=load(fullfile(folder,'reference_bank.mat'));t=r.states.Time(:);x=squeeze(r.states.Data);assert(size(x,1)==numel(t));[qr,ref]=paper_reference_series(bank,t);q=paper_euler_quaternions(x(:,1:3));err=rad2deg(2*acos(min(1,abs(sum(q.*qr,2)))));actual=rad2deg(x(:,1:3));msg=r.ErrorMessage;complete=t(end)>=floor(s.duration*1000)/1000-.001;
m=struct('id',s.id,'group',s.group,'pair_id',s.pair_id,'method',s.method,'cmg',s.cmg,'amplitude_deg',s.amplitude,'transition_s',s.transition,'frequency_Hz',s.frequency,'horizon_s',sum(s.dts),'requested_end_s',s.duration,'actual_end_s',t(end),'complete',complete,'status','INCOMPLETE','reason','','error_message',msg,'rmse_full_deg',NaN,'rmse_partial_deg',sqrt(mean(err.^2)),'peak_attitude_error_deg',max(err),'max_abs_alpha_deg',NaN,'alpha_at_end_deg',NaN,'post_transition_max_error_deg',NaN,'fallback_count',0,'controller_anomaly',false,'simulation_aborted',~isempty(msg),'predictor_domain_rejections',0,'mean_compute_s',NaN,'p95_compute_s',NaN,'max_compute_s',NaN,'over200ms_pct',NaN,'analysis_start_s',NaN,'analysis_end_s',NaN,'gain_ratio',NaN,'gain_db',NaN,'phase_lag_deg',NaN,'phase_unreliable',false,'pitch_rmse_deg',NaN,'attitude_rmse_deg',NaN,'A_ref_deg',NaN,'A_out_deg',NaN,'fit_residual_deg',NaN,'bias_deg',NaN,'trend_deg_per_s',NaN,'harmonic2_deg',NaN,'harmonic3_deg',NaN,'acceptable_tracking',false,'surface_sat_pct',NaN,'surface_rate_sat_pct',NaN,'cmg_rate_sat_pct',NaN,'aero_command_error_rms_Nm',NaN,'actual_allocation_residual_rms_Nm',NaN,'unload_active_ticks',0,'unload_paused_ticks',0,'H_initial_Nms',NaN,'H_final_Nms',NaN,'sigma_min_at_onset',NaN,'pitch_positive_support_at_onset_Nm',NaN,'pitch_negative_support_at_onset_Nm',NaN,'pitch_positive_static_support_Nm',NaN,'migrate_10deg_s',NaN,'migrate_2deg_s',NaN,'migrate_halfdeg_s',NaN,'advance_s',NaN,'pretravel_rad',NaN,'Hy_at_onset_Nms',NaN,'Hnorm_at_onset_Nms',NaN,'prepare_rmse_deg',NaN,'maneuver_rmse_deg',NaN,'maneuver_peak_deg',NaN,'post_rmse_deg',NaN,'opposite_torque_pct',NaN,'opposite_effective_samples',0,'qbar_min_Pa',NaN,'qbar_max_Pa',NaN,'V_min_mps',NaN,'V_max_mps',NaN,'alpha_min_deg',NaN,'alpha_max_deg',NaN,'height_min_m',NaN,'height_max_m',NaN,'qbar_relative_range',NaN,'height_relative_range',NaN);
if complete,m.rmse_full_deg=m.rmse_partial_deg;m.status='TRACKING_FAIL';end
ends=s.onset+s.transition;if ~isempty(s.events),ends=s.events(:,1)+s.events(:,2);end;pass=true;postmax=NaN;if s.amplitude==0 && isempty(s.events),mask=t>=2;pass=any(mask) && all(err(mask)<=1);if any(mask),postmax=max(err(mask));end;else,for finish=ends(:)',mask=t>=finish+2 & t<=finish+10;if ~any(mask) || t(end)<finish+10-.001,pass=false;else,postmax=max([postmax,max(err(mask))],[],'omitnan');pass=pass && all(err(mask)<=1);end;end;end;m.post_transition_max_error_deg=postmax;if complete && pass,m.status='SUCCESS';end
if complete && (s.amplitude~=0 || ~isempty(s.events)) && any(ends+10>t(end)+.001),m.reason='stability_window_incomplete';end
flight=squeeze(r.flight_servo_measured.Data);tf=r.flight_servo_measured.Time;flight=interp1(tf,flight,t,'previous','extrap');air=squeeze(r.flight_conditions.Data);air=interp1(r.flight_conditions.Time,air,t,'linear','extrap');alpha=rad2deg(atan2(flight(:,6),flight(:,4)));height=-flight(:,3);delta=squeeze(r.delta_actual.Data);rate=squeeze(r.delta_dot.Data);ta=squeeze(r.tau_actual.Data);cmd=squeeze(r.commands.Data);m.max_abs_alpha_deg=max(abs(alpha));m.alpha_at_end_deg=alpha(end);m.surface_sat_pct=100*mean(any(abs(delta)>=p.vehicle.delta_max(:)'-1e-5,2));m.surface_rate_sat_pct=100*mean(any(abs(rate)>=p.vehicle.delta_dot_max(:)'-1e-5,2));m.aero_command_error_rms_Nm=sqrt(mean(sum((cmd(:,1:3)-ta).^2,2)));
physical_violation=false;nu=zeros(numel(t),4);H=zeros(numel(t),3);tc=zeros(numel(t),3);migrate=NaN;
if s.cmg
assert(size(x,2)==10);accel=interp1(r.cmg_acceleration.Time,squeeze(r.cmg_acceleration.Data),t,'previous','extrap');physical_violation=any(abs(accel)>p.cmg.gddot_max+1e-6,'all');nu=interp1(r.nu_actual.Time,squeeze(r.nu_actual.Data),t,'previous','extrap');tc=interp1(r.cmg_torque.Time,squeeze(r.cmg_torque.Data),t,'linear','extrap');H=interp1(r.cmg_H.Time,squeeze(r.cmg_H.Data),t,'linear','extrap');gamma=x(:,7:10);derivedH=zeros(size(H));derivedTorque=tc;sig=zeros(numel(t),1);
for k=1:numel(t),g=gamma(k,:);A=p.cmg.h0*(-p.s0.*sin(g)+p.gxs0.*cos(g));derivedH(k,:)=sum(p.cmg.h0*(p.s0.*cos(g)+p.gxs0.*sin(g)),2)';derivedTorque(k,:)=(-A*nu(k,:)')';if strcmp(s.group,'E3'),sig(k)=min(svd(A));end;end
assert(max(abs(derivedH-H),[],'all')<1e-7 && max(abs(derivedTorque-tc),[],'all')<1e-7,'v3:truth','CMG output inconsistent with geometry');m.H_initial_Nms=norm(H(1,:));m.H_final_Nms=norm(H(end,:));m.cmg_rate_sat_pct=100*mean(any(abs(nu)>=p.cmg.gdot_max-1e-5,2));
[~,k]=min(abs(t-(s.onset-.2)));g=gamma(k,:);A=p.cmg.h0*(-p.s0.*sin(g)+p.gxs0.*cos(g));c=-A(2,:);lo=max(-p.cmg.gdot_max,nu(k,:)-p.cmg.gddot_max*.2);hi=min(p.cmg.gdot_max,nu(k,:)+p.cmg.gddot_max*.2);m.sigma_min_at_onset=min(svd(A));m.pitch_positive_support_at_onset_Nm=sum(max(c,0).*hi+min(c,0).*lo);m.pitch_negative_support_at_onset_Nm=-sum(max(c,0).*lo+min(c,0).*hi);m.pitch_positive_static_support_Nm=sum(abs(c))*p.cmg.gdot_max;m.Hy_at_onset_Nms=H(k,2);m.Hnorm_at_onset_Nms=norm(H(k,:));m.pretravel_rad=trapz(t(t<s.onset),sum(abs(nu(t<s.onset,:)),2));
movement=max(abs(gamma-gamma(1,:)),[],2);ths=[10 2 .5];onsets=nan(1,3);width=max(1,round(.6/median(diff(t))));for j=1:3,active=movement>deg2rad(ths(j));run=filter(ones(width,1),1,double(active));k=find(run>=width & t<s.onset,1);if ~isempty(k),onsets(j)=t(k-width+1);end;end;m.migrate_10deg_s=onsets(1);m.migrate_2deg_s=onsets(2);m.migrate_halfdeg_s=onsets(3);m.advance_s=s.onset-onsets(1);
if strcmp(s.group,'E3'),writetable(array2table([t,gamma,nu,H,tc,movement,sig],'VariableNames',{'time_s','g1','g2','g3','g4','nu1','nu2','nu3','nu4','Hx','Hy','Hz','tau_cmg_x','tau_cmg_y','tau_cmg_z','movement_rad','sigma_min'}),fullfile(folder,'cmg_timeseries.csv'));end
end
mask=t>=10 & t<s.onset;effective=mask & abs(ta(:,2))>1 & abs(tc(:,2))>1;m.opposite_effective_samples=sum(effective);if any(effective),m.opposite_torque_pct=100*mean(ta(effective,2).*tc(effective,2)<0);end
for item={'prepare','maneuver','post'},key=item{1};switch key,case 'prepare',mask=t>=10 & t<s.onset;case 'maneuver',mask=t>=s.onset & t<=s.onset+s.transition;case 'post',mask=t>s.onset+s.transition & t<=s.onset+s.transition+10;end;if any(mask),m.([key '_rmse_deg'])=sqrt(mean(err(mask).^2));if strcmp(key,'maneuver'),m.maneuver_peak_deg=max(err(mask));end;end;end
files=dir(fullfile(folder,'*_authority.mat'));elapsed=[];predictor_domain_fallbacks=0;if ~isempty(files),d=load(fullfile(folder,files(1).name));for j=1:numel(d.diagnostics),a=d.diagnostics{j};m.fallback_count=m.fallback_count+getfield_default(a,'fallback',0);elapsed(end+1)=getfield_default(a,'elapsed_s',NaN);reason=[getfield_default(a,'early_stop_reason','') ' ' getfield_default(a,'fallback_reason','') ' ' getfield_default(a,'failure','')];if contains(lower(reason),{'alpha outside','alpharange','assert_alpha_domain','atmosphere','height outside'}),m.predictor_domain_rejections=m.predictor_domain_rejections+1;predictor_domain_fallbacks=predictor_domain_fallbacks+logical(getfield_default(a,'fallback',false));end;end;end
pidfile=fullfile(folder,'pid_diagnostics.mat');if isfile(pidfile),d=load(pidfile);elapsed=cellfun(@(a)a.elapsed_s,d.history);eta=cellfun(@(a)a.eta,d.history);m.unload_active_ticks=sum(eta>0);m.unload_paused_ticks=sum(cellfun(@(a)ismember(a.reason,{'attitude_residual','low_qbar','no_feasible_candidate'}),d.history));desired=cell2mat(cellfun(@(a)a.tau_ref(:)',d.history,'UniformOutput',false)');desired=interp1(d.times(:),desired,t,'previous','extrap');m.actual_allocation_residual_rms_Nm=sqrt(mean(sum((desired-ta-tc).^2,2)));end
elapsed=elapsed(isfinite(elapsed));if ~isempty(elapsed),m.mean_compute_s=mean(elapsed);m.p95_compute_s=prctile(elapsed,95);m.max_compute_s=max(elapsed);m.over200ms_pct=100*mean(elapsed>.2);end;m.controller_anomaly=m.fallback_count>max(3,.1*ceil(t(end)/.2));
if ~isempty(msg),if contains(lower(msg),{'assert_alpha_domain','atmosphere','height outside','alpha outside force polar'}),m.status='MODEL_DOMAIN_FAIL';m.reason='truth_model_domain';else,m.status='CONTROLLER_FAIL';m.reason='simulation_aborted';end;elseif m.controller_anomaly && predictor_domain_fallbacks>0,m.status='MODEL_DOMAIN_FAIL';m.reason='predictor_domain_rejection_with_excess_fallback';elseif m.controller_anomaly,m.status='CONTROLLER_FAIL';m.reason='nonfatal_fallback_rate_exceeded';elseif any(~isfinite(x),'all'),m.status='CONTROLLER_FAIL';m.reason='nonfinite_state';elseif physical_violation || any(abs(delta)>p.vehicle.delta_max(:)'+1e-6,'all') || any(abs(rate)>p.vehicle.delta_dot_max(:)'+1e-6,'all') || any(abs(nu)>p.cmg.gdot_max+1e-6,'all'),m.status='CONTROLLER_FAIL';m.reason='physical_bounds';end
analysis=true(size(t));if strcmp(s.profile,'sine'),analysis=t>=8+2/s.frequency-1e-9 & t<=s.duration+1e-9;m.analysis_start_s=8+2/s.frequency;m.analysis_end_s=t(end);
if complete && t(end)>=s.duration-.001 && sum(analysis)>10 && ~ismember(m.status,{'MODEL_DOMAIN_FAIL','CONTROLLER_FAIL'})
T=t(analysis);fit=v3_fit_periodic(T,ref(analysis,2),actual(analysis,2),s.frequency,8);keys=fieldnames(fit);for fi=1:numel(keys),m.(keys{fi})=fit.(keys{fi});end;m.attitude_rmse_deg=sqrt(mean(err(analysis).^2));m.acceptable_tracking=m.gain_db>=-3 && abs(m.phase_lag_deg)<=45 && m.pitch_rmse_deg<=.5*s.amplitude;m.status='VALID_COMPLETE';if ~m.acceptable_tracking,m.status='VALID_POOR_TRACKING';end
else,if ~ismember(m.status,{'MODEL_DOMAIN_FAIL','CONTROLLER_FAIL'}),m.status='INCOMPLETE';m.reason='insufficient_last_two_cycles';end;end
end
if any(analysis),m.qbar_min_Pa=min(air(analysis,1));m.qbar_max_Pa=max(air(analysis,1));m.V_min_mps=min(air(analysis,2));m.V_max_mps=max(air(analysis,2));m.alpha_min_deg=min(alpha(analysis));m.alpha_max_deg=max(alpha(analysis));m.height_min_m=min(height(analysis));m.height_max_m=max(height(analysis));m.qbar_relative_range=range(air(analysis,1))/max(abs(mean(air(analysis,1))),eps);m.height_relative_range=range(height(analysis))/max(abs(mean(height(analysis))),eps);end
series=array2table([t,actual,ref,err,alpha,height,air(:,1:2),ta,tc,nu,H],'VariableNames',{'time_s','roll_deg','pitch_deg','yaw_deg','ref_roll_deg','ref_pitch_deg','ref_yaw_deg','attitude_error_deg','alpha_deg','height_m','qbar_Pa','V_mps','aero_x_Nm','aero_y_Nm','aero_z_Nm','cmg_x_Nm','cmg_y_Nm','cmg_z_Nm','nu1_radps','nu2_radps','nu3_radps','nu4_radps','Hx_Nms','Hy_Nms','Hz_Nms'});domain=table(t,alpha,height,air(:,1),air(:,2),'VariableNames',{'time_s','alpha_deg','height_m','qbar_Pa','V_mps'});v3_write_csv(series,fullfile(folder,'timeseries.csv'));v3_write_csv(domain,fullfile(folder,'domain_diagnostics.csv'));paper_json(fullfile(folder,'metrics.json'),m);
end
function value=getfield_default(s,key,default),if isfield(s,key),value=s.(key);else,value=default;end;end
